import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let xs = [1, 2, 3, 4]

    let s = xs.iterator().fold(0, |acc, x| acc + x)
    if s == 10 { io.println("fold-ok") } else { io.println("fold-bad") }

    let c = xs.iterator().count()
    if c == 4 { io.println("count-ok") } else { io.println("count-bad") }

    let a = xs.iterator().any(|x| x > 3)
    if a { io.println("any-ok") } else { io.println("any-bad") }

    let na = xs.iterator().any(|x| x > 9)
    if na { io.println("any-miss-bad") } else { io.println("any-miss-ok") }

    let b = xs.iterator().all(|x| x > 0)
    if b { io.println("all-ok") } else { io.println("all-bad") }

    let nb = xs.iterator().all(|x| x > 1)
    if nb { io.println("all-miss-bad") } else { io.println("all-miss-ok") }

    let r = xs.iterator().reduce(|p, q| p + q)
    match r {
        Some(v) => { if v == 10 { io.println("reduce-ok") } else { io.println("reduce-bad") } }
        None => { io.println("reduce-none") }
    }

    let f = xs.iterator().find(|x| x > 2)
    match f {
        Some(v) => { if v == 3 { io.println("find-ok") } else { io.println("find-bad") } }
        None => { io.println("find-none") }
    }

    let g = xs.iterator().find(|x| x > 9)
    match g {
        Some(v) => { io.println("find-miss-bad") }
        None => { io.println("find-miss-ok") }
    }

    return Ok(())
}
